/**
 * Under the Broom Tree
 * --------------------
 * Fleeing Jezebel, Elijah collapses under a broom tree and asks to die; an angel wakes him with bread and water. Stage: a scorched wilderness, a lone broom bush, a sleeping figure, a shining messenger kneeling beside him; harsh noon light turning gentle.
 *
 * Palette 0x4a6b3c → 0x2d4a2c · light: dream · hero: bread
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./eiljah-kit.js.
 */

import { THREE, createScene, water, oak, wheat, vineyard, flame, person, birds } from './eiljah-kit.js';

const BG = 0x4a6b3c;
const GROUND = 0x2d4a2c;

export function build(group) {
    const W = createScene(group, { seed: 203488462, bg: BG, fogNear: 55, fogFar: 220 });

    /* light — dream */
    W.lights({ sky: 0x9ab4d0, gnd: 0x5a5a52, hemi: 0.75, sun: 0xffd9a0, sunI: 0.95, sunPos: [-45, 16, 26] });

    W.disc([-30, 70, -150], 10, 0xfff8e8);
    const clouds = W.grp(group, [0, 0, 0], { name: 'cloud_bank' });
    [[-40, 44, -125, 26], [30, 50, -135, 32], [85, 42, -120, 22]].forEach(([x, y, z, s]) => {
        W.add(clouds, W.G('ico', 1, 1), W.mat(0xf0f4f8, { opacity: 0.75 }), [x, y, z], { s: [s, s * 0.22, s * 0.5] });
    });
    W.backdrop(clouds);

    /* river: animated water between grassy banks */
    water(W, group, 260, 26, -0.4, 0x101a0f, 0x345533);
    W.ground(260, 95, 0, 60, 0x2d4a2c, { amp: 0.5, j: 0.3, flat: 24, fz: 54 });
    W.ground(260, 95, 0, -64, 0x263f25, { amp: 0.6, j: 0.3, flat: 24, fz: -58 });
    W.add(group, W.G('box', 260, 0.3, 4), W.mat(0x192918), [0, -0.05, 12.6]);
    W.add(group, W.G('box', 260, 0.3, 4), W.mat(0x192918), [0, -0.05, -14.6]);

    /* trees: broadleaf shade */
    oak(W, group, -73.4, 0, -48.3, 0.92, { leaf: 0x4f8a2e, leaf2: 0x5fa036 });
    oak(W, group, 78.9, 0, 7.9, 1.24, { leaf: 0x4f8a2e, leaf2: 0x5fa036 });
    oak(W, group, -6.4, 0, -45.1, 0.98, { leaf: 0x4f8a2e, leaf2: 0x5fa036 });
    oak(W, group, -7.3, 0, -47.7, 0.96, { leaf: 0x4f8a2e, leaf2: 0x5fa036 });

    /* fields: standing grain to the horizon */
    wheat(W, group, 0, 34, 220, 110, { h: 2.1, stalk: 0x517642, head: 0x5d864b });
    /* vineyard: posts, canopies, hanging fruit */
    vineyard(W, group, 0, 30, 40, 80, { leaf: 0x4f8a2e, berry: 0x344b2a });

    /* fire: the burning mark */
    flame(W, group, 2.6, 0, 3.8, 1.1);
    W.point(0xff8a30, 2.0, 55, 0, 3, 0, 0.35);

    /* hero: the bread */
    for (let i = 0; i < 3; i++) {
        W.add(group, W.G('dod', 0.5), W.mat(0xd8b878, { rough: 0.7 }), [0 - 1 + i, 0.35, 11 + (i % 2) * 0.8 - 0.4], { s: [1, 0.5, 0.8] });
    }
    W.disc([0, 3.5, 1], 3, 0x608b4e, 0.3);

    /* figures */
    person(W, group, [-5, 0, 16], { robe: 0x8a6a44, head: 'wrap', wrap: 0x557b45, wrapTrim: 0x344b2a, beard: 'long', bend: 0.55, armR: [-0.4, 0.2], armL: [-0.3, -0.2], ry: 0.53, s: 1.11 });
    person(W, group, [4.5, 0, 17], { robe: 0x8a6a44, head: 'wrap', wrap: 0x557b45, wrapTrim: 0x344b2a, beard: 'long', bend: 0.55, armR: [-0.4, 0.2], armL: [-0.3, -0.2], ry: 0.03, s: 1.09 });

    /* birds: slow circles high above */
    birds(W, group, 7, 55, { y: 26 });

    return W.finish();
}

export default { build };
